/**
 * One player's typed, session-bound client.
 *
 * The credential and bearer are transport state, never operation input. Native
 * callers, MCP, and the CLI therefore share the same validation and lifecycle
 * behavior without gaining a way to address another body.
 */
export class WorldPlayerClient implements WorldClient {
  readonly address: WorldAddress;
  readonly #credential: string | undefined;
  readonly #transport: WorldPlayerTransport;
  readonly #sessionPersistence: WorldPlayerSessionPersistence | undefined;
  #token: SessionToken | undefined;
  #sessionValue: WorldPlayerSessionMetadata | undefined;
  #capabilitiesValue: readonly Capability[] = Object.freeze([]);
  #restoreProblem: WorldPlayerPersistedSessionProblem | undefined;

  public constructor(options: WorldPlayerClientOptions) {
    const address = typeof options.target === "string" ? parseWorldAddress(options.target) : options.target;
    this.address = Object.freeze({ ...address });
    this.#credential = options.credential;
    this.#transport = options.transport ?? callWorldTransport;
    this.#sessionPersistence = options.sessionPersistence;
    const persisted = options.sessionPersistence?.load?.();
    if (persisted === undefined) return;
    const parsed = WorldPlayerPersistedSessionSchema.safeParse(persisted);
    if (!parsed.success) {
      this.#restoreProblem =
        typeof persisted === "object" &&
        persisted !== null &&
        "version" in persisted &&
        persisted.version === 0 &&
        "reason" in persisted &&
        (persisted.reason === "legacy" || persisted.reason === "corrupt")
          ? persisted
          : { version: 0, reason: "corrupt" };
      return;
    }
    this.#restore(parsed.data);
  }

  public get joined(): boolean {
    return this.#token !== undefined;
  }

  public get session(): WorldPlayerSessionMetadata | undefined {
    return this.#sessionValue;
  }

  public get capabilities(): readonly Capability[] {
    return this.#capabilitiesValue;
  }

  public get grantedOperations(): readonly WorldOperation[] {
    return operationsFor(this.#capabilitiesValue);
  }

  public get grantedOperationNames(): readonly WorldOperationName[] {
    return this.grantedOperations.map((operation) => operation.name);
  }

  public async call<Name extends WorldOperationName>(
    name: Name,
    input: WorldOperationInput<Name>,
  ): Promise<WorldOperationResult<Name>> {
    const operation = findOperation(name);
    if (name === "world.join" && (this.#credential === undefined || this.#credential.length === 0)) {
      throw new WorldPlayerConfigError("missing_credentials", "WORLD_CREDENTIAL is not set");
    }
    if (
      name === "world.join" &&
      (typeof input !== "object" ||
        input === null ||
        !("protocolVersion" in input) ||
        input.protocolVersion !== WORLD_PROTOCOL_VERSION)
    ) {
      throw new WorldPlayerConfigError(
        "protocol_mismatch",
        `This client requires world protocol version ${String(WORLD_PROTOCOL_VERSION)}.`,
      );
    }
    const parsedInput = operation.input.parse(input) as WorldOperationInput<Name>;
    if (name !== "world.join" && this.#restoreProblem !== undefined) {
      const kind = this.#restoreProblem.reason === "legacy" ? "legacy token-only" : "corrupt";
      const refusal = outputOrRefusal(operation).parse({
        ok: false,
        code: "unauthenticated",
        message: `Saved session state is ${kind}; run world join to rejoin.`,
      }) as WorldOperationResult<Name>;
      await this.#clearSession();
      return refusal;
    }
    const request = {
      operation: name,
      input: parsedInput,
      ...(name === "world.join"
        ? this.#credential === undefined
          ? {}
          : { credential: this.#credential }
        : this.#token === undefined
          ? {}
          : { token: this.#token }),
    } as HostRequest;
    let raw: unknown;
    try {
      raw = await this.#transport(this.address, request);
    } catch (error) {
      if (!operation.idempotent) throw transportError(error);
      try {
        raw = await this.#transport(this.address, request);
      } catch (retryError) {
        throw transportError(retryError);
      }
    }
    if (
      name === "world.join" &&
      typeof raw === "object" &&
      raw !== null &&
      "ok" in raw &&
      raw.ok === true &&
      (!("protocolVersion" in raw) || raw.protocolVersion !== WORLD_PROTOCOL_VERSION)
    ) {
      throw new WorldPlayerConfigError(
        "protocol_mismatch",
        `This client requires world protocol version ${String(WORLD_PROTOCOL_VERSION)}.`,
      );
    }
    const result = outputOrRefusal(operation).parse(raw) as WorldOperationResult<Name>;

    if (
      isRefusal(result) &&
      TERMINAL_SESSION_REFUSALS.has(result.code) &&
      request.token !== undefined &&
      request.token === this.#token
    ) {
      await this.#clearSession();
      return result;
    }

    if (name === "world.join" && !isRefusal(result)) {
      const joined = result as JoinResult;
      const { token, capabilities, ...session } = joined;
      this.#restore({ version: WORLD_PLAYER_SESSION_STATE_VERSION, token, capabilities, session });
      await this.#sessionPersistence?.save?.({
        version: WORLD_PLAYER_SESSION_STATE_VERSION,
        token,
        capabilities,
        session,
      });
      return { ...joined, token: WORLD_PLAYER_REDACTED_TOKEN } as WorldOperationResult<Name>;
    }

    if (name === "world.leave" && !isRefusal(result)) {
      await this.#clearSession();
    }

    return result;
  }

  public async join(request: WorldOperationInput<"world.join">): Promise<JoinResult> {
    return await this.success("world.join", request);
  }

  public async sessionStatus(): Promise<SessionStatus> {
    return await this.success("world.session", {});
  }

  public async leave(): Promise<LeaveResult> {
    return await this.success("world.leave", {});
  }

  public async observe(): Promise<Observation> {
    return await this.success("play.observe", {});
  }

  public async act(request: WorldOperationInput<"play.act">): Promise<ActResult> {
    return await this.success("play.act", request);
  }

  public async latestFrame(): Promise<Frame> {
    return await this.success("play.frame", {});
  }

  /** The request/response transport has no push channel, so public clients poll. */
  public async *frames(): AsyncIterable<Frame> {
    let current: Frame | undefined;
    while (this.joined) {
      let incoming: Frame;
      try {
        incoming = await this.latestFrame();
      } catch (error) {
        if (error instanceof WorldPlayerRefusalError && !this.joined) return;
        throw error;
      }
      if (incoming.sessionId !== this.#sessionValue?.sessionId) {
        throw new Error("frame belongs to a different session");
      }
      if (current !== undefined && current.sessionId === incoming.sessionId) {
        const sameGeneration = current.bodyGeneration === incoming.bodyGeneration;
        // A sequential poll cannot receive an older response after this exact
        // zero marker. It is the only unambiguous same-generation counter reset;
        // lower nonzero frames remain stale and are discarded below.
        const restarted = sameGeneration && current.frame > 0 && incoming.frame === 0;
        if (
          incoming.bodyGeneration < current.bodyGeneration ||
          (sameGeneration && incoming.frame <= current.frame && !restarted)
        ) {
          await delay(16);
          continue;
        }
        const dropped =
          sameGeneration && !restarted
            ? Math.max(incoming.dropped, incoming.frame - current.frame - 1)
            : incoming.dropped;
        current = dropped === incoming.dropped ? incoming : { ...incoming, dropped };
      } else {
        current = incoming;
      }
      yield current;
      await delay(16);
    }
  }

  public async watch(request: WorldOperationInput<"play.watch">): Promise<WatchResult> {
    return await this.success("play.watch", request);
